//! The definitions of the EPSG registry, as data.
//!
//! The `crs-definitions` crate finds a definition with `from_code`, one match of 6,184 arms. In
//! WebAssembly that is a single function so large that V8's optimising compiler runs out of memory
//! when it tries to compile it after a few dozen calls, and the process (Node 24) aborts. So the
//! definitions are held as a table of the crate's own constants (`table.rs`, generated by
//! `scripts/generate-crs-table`) and found by binary search, and `from_code` is only called by the
//! test that checks the table against it.

use crs_definitions::Def;

mod table;

/// The definition of an EPSG code, `None` if the registry does not have it.
pub(crate) fn get(code: u16) -> Option<Def> {
    let at = table::DEFINITIONS
        .binary_search_by_key(&code, |definition| definition.code)
        .ok()?;
    table::DEFINITIONS.get(at).copied()
}

/// Every definition, in the order of their codes.
pub(crate) fn all() -> impl Iterator<Item = Def> {
    table::DEFINITIONS.iter().copied()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_table_is_what_from_code_says_for_every_code() {
        // The one place `from_code` is called: if the crate is updated and the table is not made
        // again (`scripts/generate-crs-table`), this is what fails.
        let mut found = 0;
        for code in 0..=u16::MAX {
            let from_the_match = crs_definitions::from_code(code);
            assert_eq!(get(code), from_the_match, "EPSG:{code}");
            found += usize::from(from_the_match.is_some());
        }
        assert_eq!(found, 6_184);
        assert_eq!(all().count(), found);
    }

    #[test]
    fn the_table_is_in_the_order_of_its_codes_without_a_repeat() {
        let codes: Vec<u16> = all().map(|definition| definition.code).collect();
        assert!(codes.windows(2).all(|pair| pair[0] < pair[1]));
    }

    #[test]
    fn a_code_that_is_not_there_is_not_found() {
        assert_eq!(get(0), None);
        assert_eq!(get(u16::MAX), None);
        assert!(get(4326).is_some());
    }
}
